-- Part H is isolated by release_stage. No existing person, time or financial rows are changed.
CREATE TABLE holiday_rules(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),jurisdiction text NOT NULL,version text NOT NULL,effective_from text NOT NULL,effective_through text NOT NULL,configuration text NOT NULL,content_hash text NOT NULL,created_at text NOT NULL,created_by text REFERENCES employees(id),reference text NOT NULL,UNIQUE(org_id,release_stage,jurisdiction,version));
CREATE TABLE holiday_assignments(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),employee_id text NOT NULL REFERENCES employees(id),country text NOT NULL,province text NOT NULL,jurisdiction text NOT NULL,calendar text NOT NULL,office_id text REFERENCES units(id),location text NOT NULL,rule_id text NOT NULL REFERENCES holiday_rules(id),effective_on text NOT NULL,weekdays text NOT NULL,daily_seconds integer NOT NULL,easter_choice text NOT NULL,created_by text NOT NULL REFERENCES employees(id),created_at text NOT NULL,reference text NOT NULL);
CREATE TABLE holiday_company_events(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),name text NOT NULL,on_date text NOT NULL,jurisdiction text NOT NULL,kind text NOT NULL CHECK(kind IN('Optional observance','Paid company holiday','Closure')),calendar_key text NOT NULL,closed integer NOT NULL DEFAULT 0,guaranteed_minutes integer NOT NULL DEFAULT 0,targets text NOT NULL,target_reference text NOT NULL,cancelled_at text,revision integer NOT NULL DEFAULT 1,created_by text NOT NULL REFERENCES employees(id),created_at text NOT NULL,updated_at text NOT NULL,reference text NOT NULL);
CREATE TABLE holiday_event_versions(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL,event_id text NOT NULL REFERENCES holiday_company_events(id),revision integer NOT NULL,snapshot text NOT NULL,actor_id text NOT NULL REFERENCES employees(id),created_at text NOT NULL,UNIQUE(event_id,revision));
CREATE TABLE holiday_histories(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),employee_id text NOT NULL REFERENCES employees(id),from_date text NOT NULL,through_date text NOT NULL,configuration text NOT NULL,status text NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Approved','Rejected')),revision integer NOT NULL DEFAULT 1,reference text NOT NULL,created_by text NOT NULL REFERENCES employees(id),created_at text NOT NULL,reviewed_by text REFERENCES employees(id),reviewed_at text,review_note text NOT NULL DEFAULT '');
CREATE TABLE holiday_exceptions(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),employee_id text NOT NULL REFERENCES employees(id),holiday_date text NOT NULL,kind text NOT NULL,configuration text NOT NULL,status text NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Approved','Rejected')),revision integer NOT NULL DEFAULT 1,reference text NOT NULL,created_by text NOT NULL REFERENCES employees(id),created_at text NOT NULL,reviewed_by text REFERENCES employees(id),reviewed_at text,review_note text NOT NULL DEFAULT '');
CREATE TABLE holiday_assessments(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),employee_id text NOT NULL REFERENCES employees(id),holiday_date text NOT NULL,configuration text NOT NULL,source_hash text NOT NULL,status text NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Approved','Rejected')),revision integer NOT NULL DEFAULT 1,reference text NOT NULL,created_by text NOT NULL REFERENCES employees(id),created_at text NOT NULL,reviewed_by text REFERENCES employees(id),reviewed_at text,review_note text NOT NULL DEFAULT '');
CREATE TABLE holiday_allocations(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),employee_id text NOT NULL REFERENCES employees(id),holiday_date text NOT NULL,component text NOT NULL,payroll_id text NOT NULL REFERENCES payroll(id),assessment_id text NOT NULL REFERENCES holiday_assessments(id),paid_on text NOT NULL,amount_minor integer NOT NULL,currency text NOT NULL,snapshot text NOT NULL,created_at text NOT NULL,UNIQUE(release_stage,employee_id,holiday_date,component));
CREATE TABLE holiday_reconciliations(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL,employee_id text NOT NULL REFERENCES employees(id),holiday_date text NOT NULL,payroll_id text NOT NULL REFERENCES payroll(id),assessment_id text NOT NULL REFERENCES holiday_assessments(id),status text NOT NULL DEFAULT 'Pending' CHECK(status IN('Pending','Resolved')),detail text NOT NULL,created_at text NOT NULL,resolved_by_item text REFERENCES payroll_earnings(id),resolved_at text,UNIQUE(payroll_id,assessment_id));
CREATE TABLE holiday_private_records(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),employee_id text NOT NULL REFERENCES employees(id),configuration text NOT NULL,created_by text NOT NULL REFERENCES employees(id),created_at text NOT NULL,reference text NOT NULL,retain_until text NOT NULL);
CREATE TABLE holiday_audit(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),employee_id text REFERENCES employees(id),actor_id text NOT NULL REFERENCES employees(id),entity text NOT NULL,target_id text NOT NULL,action text NOT NULL,detail text NOT NULL,created_at text NOT NULL);
CREATE TABLE holiday_consents(id text PRIMARY KEY,org_id text NOT NULL REFERENCES organizations(id),release_stage text NOT NULL CHECK(release_stage IN('preview','production')),employee_id text NOT NULL REFERENCES employees(id),exception_id text NOT NULL REFERENCES holiday_exceptions(id),consented integer NOT NULL CHECK(consented IN(0,1)),created_at text NOT NULL,note text NOT NULL);
CREATE INDEX holiday_consent_latest ON holiday_consents(exception_id,created_at);
DO $holiday_guards$
DECLARE t text;
BEGIN
 FOREACH t IN ARRAY ARRAY['holiday_rules','holiday_assignments','holiday_company_events','holiday_event_versions','holiday_histories','holiday_exceptions','holiday_assessments','holiday_allocations','holiday_reconciliations','holiday_private_records','holiday_consents','holiday_audit'] LOOP
  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
  EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['holiday_rules','holiday_assignments','holiday_event_versions','holiday_allocations','holiday_private_records','holiday_consents','holiday_audit'] LOOP
  EXECUTE format('CREATE TRIGGER holiday_history_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.walshken_reject_history_mutation()',t);
 END LOOP;
 FOREACH t IN ARRAY ARRAY['holiday_histories','holiday_exceptions','holiday_assessments'] LOOP
  EXECUTE format('CREATE TRIGGER holiday_approved_immutable BEFORE UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.protect_approved_payroll_input()',t);
 END LOOP;
END;
$holiday_guards$;
CREATE INDEX holiday_rule_effective ON holiday_rules(org_id,release_stage,jurisdiction,effective_from);
CREATE INDEX holiday_assignment_effective ON holiday_assignments(employee_id,release_stage,effective_on,created_at);
CREATE INDEX holiday_company_calendar ON holiday_company_events(org_id,release_stage,jurisdiction,on_date);
CREATE INDEX holiday_history_coverage ON holiday_histories(employee_id,release_stage,status,from_date,through_date);
CREATE INDEX holiday_exception_employee ON holiday_exceptions(employee_id,release_stage,holiday_date,status);
CREATE INDEX holiday_assessment_employee ON holiday_assessments(employee_id,release_stage,holiday_date,created_at);
CREATE INDEX holiday_private_employee ON holiday_private_records(employee_id,release_stage,created_at);
CREATE INDEX holiday_reconciliation_scope ON holiday_reconciliations(employee_id,release_stage,status);
CREATE INDEX holiday_audit_scope ON holiday_audit(org_id,release_stage,created_at);
CREATE INDEX holiday_allocations_payroll ON holiday_allocations(payroll_id);
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-FED-2026-v1','walshken','preview','CA-FED','CA-FED-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-FED","name":"Canada — federally regulated employment","country":"CA","province":"FED","version":"CA-FED-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.canada.ca/en/services/jobs/workplace/federal-labour-standards/vacations-holidays.html"],"required":["new-year","good-friday","canada-day","labour","christmas","victoria","truth","thanksgiving","remembrance","boxing"],"optional":["easter-monday"],"special":[],"eligibility":"Federal jurisdiction applies to federally regulated employment, not every Canadian workplace. Check work, leave, substitution and collective-agreement provisions.","calculation":"Standard wages excluding overtime in the four weeks before the holiday week ÷ 20; separate commission and continuous-operation rules.","native":false},"employment":null}','08ba365288b3e83632e5912d2ceb3c7d21d8efdcee3a13f65f60020662af342f','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-AB-2026-v1','walshken','preview','CA-AB','CA-AB-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-AB","name":"Alberta","country":"CA","province":"AB","version":"CA-AB-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.alberta.ca/alberta-general-holidays"],"required":["new-year","good-friday","canada-day","labour","christmas","family","victoria","thanksgiving","remembrance"],"optional":["easter-monday","heritage","truth","boxing"],"special":[],"eligibility":"At least 30 actual workdays in the preceding 12 months. Regular workday or work on the holiday; statutory absence conditions apply. Fixed work schedule or the five-of-nine test determines a regular day.","calculation":"Average ordinary daily wages over either permitted 28-day window. Eligible regular day: day pay; if worked, day pay plus 1.5× work or ordinary work/overtime plus a future paid day. Eligible non-regular worked day: 1.5× work.","native":true},"employment":{"jurisdiction":"CA-AB","category":"Standard adult employee","version":"CA-AB-employment-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.alberta.ca/alberta-general-holidays","https://www.alberta.ca/overtime-hours-overtime-pay","https://www.alberta.ca/hours-work-rest","https://www.alberta.ca/vacation-pay","https://www.alberta.ca/payment-earnings"],"maxShiftMinutes":720,"minRestMinutes":480,"changeNoticeMinutes":1440,"restHoursPerWeek":24,"firstBreakAfterMinutes":300,"secondBreakFromMinutes":600,"minimumBreakMinutes":30,"minimumSplitMinutes":15,"dailyOvertimeHours":8,"weeklyOvertimeHours":44,"overtimeMultiplier":"1.5","vacationInitialPercent":"4","vacationLongServicePercent":"6","vacationLongServiceYears":5,"vacationInitialWeeks":2,"vacationLongServiceWeeks":3,"recordsYears":3,"paymentDeadlineDays":10,"minimumHourlyMinor":1500,"currency":"CAD","holidayMinimumWorkdays":30,"holidayLookbackMonths":12,"holidayRegularDayWeeks":9,"holidayRegularDayOccurrences":5,"holidayAverageWageDays":28,"holidayPremiumMultiplier":"1.5","holidayEngine":"Alberta standard"}}','fbac579b59530839552beb64f0e5a0f7ad02d725e1993e85de25f15460a92159','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-BC-2026-v1','walshken','preview','CA-BC','CA-BC-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-BC","name":"British Columbia","country":"CA","province":"BC","version":"CA-BC-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.bclaws.gov.bc.ca/civix/document/id/complete/statreg/00_96113_01"],"required":["new-year","good-friday","canada-day","labour","christmas","family","victoria","august","truth","thanksgiving","remembrance"],"optional":["easter-monday","boxing"],"special":[],"eligibility":"Normally employed 30 calendar days and worked/earned wages on 15 of the preceding 30 days; averaging-agreement and occupation provisions may differ.","calculation":"Average day’s pay over the preceding 30 days, excluding overtime. Qualified holiday work adds 1.5× up to 12 hours and 2× thereafter.","native":false},"employment":null}','75bc829076a13d67842f8e4d1b4a8127ace029e0ff99af803c85629f06c9db05','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-SK-2026-v1','walshken','preview','CA-SK','CA-SK-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-SK","name":"Saskatchewan","country":"CA","province":"SK","version":"CA-SK-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.saskatchewan.ca/Business/Employment-Standards/Public-Statutory-Holidays/Paying-Employees-for-Public-Holidays"],"required":["new-year","good-friday","canada-day","labour","christmas","family","victoria","august","thanksgiving","remembrance"],"optional":["easter-monday","boxing","truth"],"special":[],"eligibility":"Public-holiday entitlement applies to employees, including new employees. Construction and modified-work arrangements have distinct rules.","calculation":"Normally 5% of eligible wages over the preceding 28 days, including applicable vacation/holiday pay and excluding overtime; holiday work adds 1.5×. Holiday weeks affect overtime thresholds.","native":false},"employment":null}','a1043c9bad8c153559b10e499f846e834a526aa5287108bbf95f2ff5121dc026','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-MB-2026-v1','walshken','preview','CA-MB','CA-MB-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-MB","name":"Manitoba","country":"CA","province":"MB","version":"CA-MB-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.gov.mb.ca/labour/standards/doc,gen-holidays,factsheet.html"],"required":["new-year","good-friday","canada-day","labour","christmas","family","victoria","truth","thanksgiving"],"optional":["easter-monday","boxing"],"special":["remembrance"],"eligibility":"Most employees qualify, subject to unauthorized adjacent absences and required holiday work. Remembrance Day is governed by separate law.","calculation":"Regular day’s wages for consistent hours; otherwise normally 5% of wages excluding overtime in the preceding four weeks. Worked-holiday rules and exceptions apply.","native":false},"employment":null}','9d58b3c8c6b913bc91225b3be60944e94d5c2ec9ea58e750b9c9e58675a9e470','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-ON-2026-v1','walshken','preview','CA-ON','CA-ON-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-ON","name":"Ontario","country":"CA","province":"ON","version":"CA-ON-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.ontario.ca/document/your-guide-employment-standards-act-0/public-holidays"],"required":["new-year","good-friday","canada-day","labour","christmas","family","victoria","thanksgiving","boxing"],"optional":["easter-monday","august","truth","remembrance"],"special":[],"eligibility":"Normally requires the last and first scheduled shifts around the holiday, unless reasonable cause applies. Written agreements and occupational exceptions affect worked holidays.","calculation":"Eligible regular wages plus applicable vacation pay in the four workweeks before the holiday workweek ÷ 20; worked-day premium or substitute-day agreement rules apply.","native":false},"employment":null}','aadcd611235834ead48ed2ab298c799cbcce2e1c356048673181442e922f77cb','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-QC-2026-v1','walshken','preview','CA-QC','CA-QC-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-QC","name":"Québec","country":"CA","province":"QC","version":"CA-QC-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.cnesst.gouv.qc.ca/en/working-conditions/leave/statutory-holidays/statutory-holidays"],"required":["new-year","quebec-easter","victoria","quebec-national","canada-day","labour","thanksgiving","christmas"],"optional":["truth","remembrance","boxing"],"special":[],"eligibility":"No general minimum service period. Unauthorized adjacent absence can affect entitlement; June 24 has its own rules. The employer chooses Good Friday or Easter Monday.","calculation":"Generally 1/20 of wages excluding overtime over the four complete pay weeks before the holiday week; commission uses 1/60 over 12 weeks. June 24 and compensatory leave have separate requirements.","native":false},"employment":null}','bd2386a5fbaf5cd03080654e19927bc35e31f124986745ef30e0f1eaad0a5119','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-NB-2026-v1','walshken','preview','CA-NB','CA-NB-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-NB","name":"New Brunswick","country":"CA","province":"NB","version":"CA-NB-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.gnb.ca/en/topic/jobs-workplaces/labour-market-workforce/employment-standards/holiday-vacation.html"],"required":["new-year","good-friday","canada-day","labour","christmas","family","august","remembrance"],"optional":["victoria","thanksgiving","truth","boxing"],"special":[],"eligibility":"Normally 90 calendar days of employment in the previous 12 months and scheduled adjacent attendance, subject to valid reasons. Worked-holiday premium rights are distinct.","calculation":"Qualified employees receive regular holiday day pay; all holiday work normally pays 1.5×. Authorized alternative 4% arrangements and exemptions require their own verified policy.","native":false},"employment":null}','fb468cdcc4b65a055ba6359e530171a913290ddf82047cfcb7f0d04f51a1379b','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-NS-2026-v1','walshken','preview','CA-NS','CA-NS-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-NS","name":"Nova Scotia","country":"CA","province":"NS","version":"CA-NS-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://novascotia.ca/lae/employmentrights/holidaypay.asp"],"required":["new-year","good-friday","canada-day","labour","christmas","family"],"optional":["victoria","august","truth","thanksgiving","boxing"],"special":["remembrance"],"eligibility":"Normally entitled to pay on at least 15 of the preceding 30 days, with required adjacent attendance subject to authorized/statutory absences. Remembrance Day uses separate legislation.","calculation":"Regular day’s holiday pay for qualified employees, with applicable holiday-work premium. Continuous operations and Remembrance Day require separate treatment.","native":false},"employment":null}','811f3b32f70753dfa01654147a9e091afcec27a5cb6b9056b73fa7f5ff579b93','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-PE-2026-v1','walshken','preview','CA-PE','CA-PE-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-PE","name":"Prince Edward Island","country":"CA","province":"PE","version":"CA-PE-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.princeedwardisland.ca/en/information/workforce-and-advanced-learning/paid-holidays"],"required":["new-year","good-friday","canada-day","labour","christmas","family","truth","remembrance"],"optional":["victoria","august","thanksgiving","boxing"],"special":[],"eligibility":"Check the Act’s service, paid-days, adjacent-shift, reasonable-cause and holiday-work conditions. Substitute days must respect the applicable agreement and vacation deadline.","calculation":"Published 2026 guidance uses 5% of eligible regular wages in the preceding four weeks, including applicable vacation/holiday pay and excluding overtime. Worked holidays use the statutory premium or agreed paid day.","native":false},"employment":null}','f74d435c2021b9e14db36ffe45d5649cd6b8cb74421c0e75ebd0fb6f04562d5a','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-NL-2026-v1','walshken','preview','CA-NL','CA-NL-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-NL","name":"Newfoundland and Labrador","country":"CA","province":"NL","version":"CA-NL-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.gov.nl.ca/ecc/files/Your-Rights-At-Work.pdf"],"required":["new-year","good-friday","canada-day","labour","christmas","remembrance"],"optional":["victoria","august","truth","thanksgiving","boxing"],"special":[],"eligibility":"Day-off pay and premium for actual holiday work have different qualification rules. Collective agreements and proclaimed days must be checked.","calculation":"Qualifying unworked holiday: regular day’s pay. Actual work: twice the regular rate or the lawful additional paid-day/vacation alternative.","native":false},"employment":null}','77c04bc66cdb46159e621232b1787ee3660cdeebd3ddae5ee6f5af71cbaa3a98','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-YT-2026-v1','walshken','preview','CA-YT','CA-YT-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-YT","name":"Yukon","country":"CA","province":"YT","version":"CA-YT-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://yukon.ca/en/doing-business/employer-responsibilities/find-yukon-statutory-holiday"],"required":["new-year","good-friday","canada-day","labour","christmas","victoria","indigenous","discovery","truth","thanksgiving","remembrance"],"optional":["yukon-heritage","easter-monday","boxing"],"special":[],"eligibility":"Normally 30 calendar days, wages/work in the preceding two weeks and required adjacent/holiday attendance. Actual work on a holiday has separate eligibility provisions.","calculation":"Use the applicable regular/variable-day calculation and worked-day premium or substitute-day rules. A non-working-day holiday generally moves to the next working day.","native":false},"employment":null}','5e88901e35800e0176a78062ec05b2964dee69d5af9d62201f1d9609e7ca8dac','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-NT-2026-v1','walshken','preview','CA-NT','CA-NT-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-NT","name":"Northwest Territories","country":"CA","province":"NT","version":"CA-NT-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.ece.gov.nt.ca/en/services/employment-standards/frequently-asked-questions"],"required":["new-year","good-friday","canada-day","labour","christmas","victoria","indigenous","august","truth","thanksgiving","remembrance"],"optional":["easter-monday","boxing"],"special":[],"eligibility":"Normally 30 days worked in the preceding 12 months, required adjacent/holiday attendance, with applicable leave exclusions.","calculation":"Qualified average day pay plus 1.5× if worked, or a lawful paid substitute day. Holiday-week overtime and alternative work arrangements are separate rules.","native":false},"employment":null}','e817485d37d1c18cbc44c44e168740413f0a68ef1a30e0c02d6b55f1b33dee86','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
INSERT INTO holiday_rules(id,org_id,release_stage,jurisdiction,version,effective_from,effective_through,configuration,content_hash,created_at,reference) VALUES('holiday-rule-CA-NU-2026-v1','walshken','preview','CA-NU','CA-NU-calendar-2026-v1','2026-01-01','2028-12-31','{"calendar":{"code":"CA-NU","name":"Nunavut","country":"CA","province":"NU","version":"CA-NU-calendar-2026-v1","effectiveFrom":"2026-01-01","effectiveThrough":"2028-12-31","verifiedOn":"2026-11-23","sources":["https://www.gov.nu.ca/en/employment-training-and-career-development/labour-and-employment-standards-nunavut"],"required":["new-year","good-friday","canada-day","labour","christmas","victoria","nunavut","august","truth","thanksgiving","remembrance"],"optional":["easter-monday","boxing"],"special":[],"eligibility":"Normally 30 days worked in the preceding year and required adjacent/holiday attendance, with applicable maternity/parental leave exclusions.","calculation":"Apply the territory’s qualified holiday pay and worked-holiday premium/substitute-day requirements, independently of public-service-only holidays.","native":false},"employment":null}','dffc102f72f9bec726568edf28f70f04aa7a3215eb4c515c42c39e79f02c5c05','2026-11-23T00:00:00.000Z','Official source package verified 2026-11-23; initial Alberta standard adult calculation scope');
